class _CurrencyListPageState extends State<CurrencyListPage> 
    with SingleTickerProviderStateMixin, WidgetsBindingObserver {

  late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;
  late final AnimationController _fadeController;
  late Future<void> _initialLoadFuture; // Changed to void since we handle list in notifier

  List<CurrencyModel> _allCurrencies = [];
  int _currentPage = 0;
  bool _hasMore = true;
  bool _isLoadingNextPage = false;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this); // Add observer
    _initAnimation();
    _loadInitialData(); // Renamed from _initData for clarity
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this); // Remove observer
    _filteredCurrenciesNotifier.dispose();
    _fadeController.dispose();
    super.dispose();
  }

  @override
  Future<void> didChangeAppLifecycleState(AppLifecycleState state) async {
    if (state == AppLifecycleState.resumed) {
      await _refreshData(); // Refresh when app comes back to foreground
    }
  }

  void _loadInitialData() {
    final repository = context.read<CurrencyRepository>();

    _initialLoadFuture = repository.fetchRates(const CurrencyPageRequest(base: 'USD', page: 0)).then((CurrencyPage page) {
      setState(() {
        _allCurrencies = page.items;
        _currentPage = page.page + 1; // Next page to load
        _hasMore = page.hasMore;
        _filteredCurrenciesNotifier.value = _allCurrencies;
      });

      repository.saveCurrencyList(_allCurrencies);
      _fadeController.forward();
    });
  }

  Future<void> _loadNextPage() async {
    if (!_hasMore || _isLoadingNextPage) return;

    setState(() => _isLoadingNextPage = true);

    final repository = context.read<CurrencyRepository>();
    final page = await repository.fetchRates(CurrencyPageRequest(base: 'USD', page: _currentPage));

    setState(() {
      _allCurrencies.addAll(page.items);
      _filteredCurrenciesNotifier.value = List.from(_allCurrencies, growable: false);
      _currentPage++;
      _hasMore = page.hasMore;
      _isLoadingNextPage = false;
    });
  }

  Future<void> _refreshData() async {
    final repository = context.read<CurrencyRepository>();

    setState(() => _isLoadingNextPage = true); // Reuse this as loading state

    await repository.fetchRates(const CurrencyPageRequest(base: 'USD', page: 0)).then((CurrencyPage page) {
      setState(() {
        _allCurrencies = page.items;
        _currentPage = page.page + 1;
        _hasMore = page.hasMore;
        _filteredCurrenciesNotifier.value = List.from(_allCurrencies, growable: false);
        _isLoadingNextPage = false;
      });

      repository.saveCurrencyList(_allCurrencies);
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.currencyRate)),
      body: FutureBuilder(
        future: _initialLoadFuture,
        builder: (context, snapshot) {
          if (!snapshot.hasData) return const SizedBox.shrink();

          return FadeTransition(
            opacity: _fadeController.view,
            child: Column(
              children: [
                Padding(
                  padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
                  child: SearchView(onChanged: _filterCurrencies),
                ),
                Expanded(
                  child: ValueListenableBuilder<List<CurrencyModel>>(
                    valueListenable: _filteredCurrenciesNotifier,
                    builder: (context, data, _) {
                      return ListView.builder(
                        itemCount: data.length + (_hasMore ? 1 : 0), // Add space for "Show more" button if hasMore
                        itemBuilder: (context, index) {
                          if (index >= data.length) {
                            // Show "Show more" button at the end of list
                            return _buildLoadMoreButton();
                          }

                          final currency = data[index];
                          return Padding(
                            key: ValueKey(currency.id),
                            padding: index == 0 ? const EdgeInsets.only(top: 20) : const EdgeInsets.only(top: 10),
                            child: CurrencyCard(model: currency),
                          );
                        },
                        padding: const EdgeInsets.fromLTRB(22, 0, 22, 40),
                      );
                    },
                  ),
                ),
              ],
            ),
          );
        },
      ),
    );
  }

  Widget _buildLoadMoreButton() {
    return Padding(
      padding: const EdgeInsets.all(16.0),
      child: Visibility(
        visible: _hasMore && !_isLoadingNextPage, // Show only when there are more pages and not loading
        child: ElevatedButton(
          onPressed: _loadNextPage,
          child: Text(context.loc.showMore),
        ),
      ),
    );
  }

  void _filterCurrencies(String query) {
    final String lowerQuery = query.toLowerCase();
    final Iterable<CurrencyModel> result = _allCurrencies.where((CurrencyModel currency) {
      return currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery);
    });

    _filteredCurrenciesNotifier.value = List.from(result, growable: false); // Create new list for ValueNotifier
  }
}
